fetch dt.davis.problems, from:-30d
| filter not(dt.davis.is_duplicate)
| makeTimeseries count(), interval:1d, by:{event.category}

fetch spans, from:-24h
| filter iAny(span.events[][span_event.name] == "exception")
| makeTimeseries occurrences = count(), interval:1h, by:{dt.service.name}
